function validate([s, t]) {
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (t < 1 || t > 100000) return 't is a whole number from 1 to 10^5.';
  return null;
}

