function lengthAfterTransformations(s, t) {
  // fromZ[k] is the length of what one 'z' grows into after k more rounds; every letter's
  // length follows from it, without tracking letter counts round by round.
  const MOD = 1000000007;
  const fromZ = new Array(t + 1).fill(1);
  const grow = (letter, rounds) => {
    // A letter stays a single letter until it has become 'z' and then been rewritten.
    const untilZ = 25 - letter;
    return rounds <= untilZ ? 1 : fromZ[rounds - untilZ];
  };
  // 'z' becomes "ab"; after that the 'a' and the 'b' each grow for the remaining rounds.
  for (let k = 1; k <= t; k++) fromZ[k] = (grow(0, k - 1) + grow(1, k - 1)) % MOD;
  let total = 0;
  for (const ch of s) total = (total + grow(ch.charCodeAt(0) - 97, t)) % MOD;
  return total;
}

