function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const n = 10000 - pick(50);
    const late = rand() < 0.5;
    const s = Array.from({ length: n }, () => letters[late ? 25 - pick(6) : pick(26)]).join('');
    return [s, 100000 - pick(1000)];
  }
  // Small strings, often of late letters so that 'z' splits happen within a few rounds;
  // some runs go to a few thousand rounds so the modulus is exercised too.
  const n = 1 + pick(8);
  const style = pick(3);
  const s = Array.from({ length: n }, () => letters[style === 0 ? pick(26) : style === 1 ? 20 + pick(6) : 25 - pick(3)]).join('');
  const t = rand() < 0.7 ? 1 + pick(60) : 1 + pick(3000);
  return [s, t];
}
